-- Additive bounded metadata reads. No SQL bodies, secrets or customer row data.
-- The explicit result cap is not pagination or complete family implementation.
BEGIN;
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.sandy_operation_registry
    WHERE operation = 'supabase.projects.get' AND handler = 'sandy-provider-read-api'
      AND permission_scope = 'infrastructure:read' AND is_mutation = false) THEN
    RAISE EXCEPTION 'owner-only project read contract prerequisite missing';
  END IF;
END $$;
INSERT INTO public.sandy_operation_registry (
  operation, domain, description, permission_scope, is_mutation,
  input_schema, output_schema, handler, api_exposed, ui_exposed, ai_exposed,
  verified, implementation_state, source_repository, source_path,
  dependencies, error_contract, retry_policy, rollback_policy
)
SELECT contracts.operation, 'supabase', contracts.description,
  'infrastructure:read', false,
  '{"type":"object","properties":{},"additionalProperties":false}'::jsonb,
  contracts.output_schema, 'sandy-provider-read-api', true, false, true,
  false, 'deployed_unverified', base.source_repository, base.source_path,
  CASE WHEN contracts.operation = 'supabase.database.cron.jobs.list'
    THEN base.dependencies || '["extension:pg_cron"]'::jsonb ELSE base.dependencies END,
  base.error_contract, base.retry_policy, base.rollback_policy
FROM public.sandy_operation_registry AS base
