  ('supabase.database.locks.list', 'Read up to 200 aggregate lock type, mode and grant counts without PIDs, resources, queries or client data; bounded metadata only, possibly_truncated=true at limit; contract v1.0.0.', '{"type":"object","required":["ok","contract_version","operation","project_id","result","result_limit","possibly_truncated","observed_at","provider_request_id"],"properties":{"ok":{"const":true},"contract_version":{"const":"1.0.0"},"operation":{"const":"supabase.database.locks.list"},"project_id":{"const":"zmqlyygzqoidkcwdysok"},"result":{"type":"array","maxItems":200,"items":{"type":"object","required":["lock_type","mode","granted","count"],"properties":{"lock_type":{"type":"string"},"mode":{"type":"string"},"granted":{"type":"boolean"},"count":{"type":"integer","minimum":1}},"additionalProperties":false}},"result_limit":{"const":200},"possibly_truncated":{"type":"boolean"},"observed_at":{"type":"string","format":"date-time"},"provider_request_id":{"type":["string","null"]}},"additionalProperties":false}'::jsonb),
